<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowDownToLine, BookOpen, Code2, FileText, FolderOpen, LayoutGrid, Search, Sparkles, Trash2, X } from '@lucide/vue'
import { useRouter } from 'vue-router'
type Resource = { id: number; type: string; title: string; desc: string; meta: string; icon: typeof FileText }
const router = useRouter(); const search = ref(''); const type = ref('全部'); const preview = ref<Resource | null>(null); const exportOpen = ref<number | null>(null); const deleteTarget = ref<Resource | null>(null)
const filters = ['全部','文档','思维导图','代码','闪卡','项目','可视化']
const resources = ref<Resource[]>([{ id: 1, type: '文档', title: 'CNN 入门教程', desc: '从卷积层到经典架构的完整讲解', meta: '7月13日 · 12页', icon: FileText }, { id: 2, type: '思维导图', title: 'CNN 知识结构', desc: '卷积、池化与全连接层的关系', meta: '7月13日 · 思维导图', icon: LayoutGrid }, { id: 3, type: '代码', title: 'PyTorch CNN 示例', desc: '一个可以直接运行的图像分类项目', meta: '7月12日 · Python', icon: Code2 }, { id: 4, type: '闪卡', title: 'CNN 核心概念', desc: '记忆卡片 · 共 12 张', meta: '7月11日 · 12张', icon: BookOpen }, { id: 5, type: '项目', title: '手写数字识别', desc: '从数据处理到模型训练的完整实战', meta: '7月10日 · 项目实战', icon: FolderOpen }, { id: 6, type: '可视化', title: '卷积过程可视化', desc: '用交互方式理解卷积核的移动过程', meta: '7月9日 · 交互式', icon: Sparkles }])
const filtered = computed(() => resources.value.filter(item => (type.value === '全部' || item.type === type.value) && (!search.value || `${item.title}${item.desc}`.toLowerCase().includes(search.value.toLowerCase()))))
const remove = () => { if (deleteTarget.value) { resources.value = resources.value.filter(item => item.id !== deleteTarget.value?.id); deleteTarget.value = null } }
const exportResource = (format: string) => { exportOpen.value = null; window.alert(`演示模式：已准备导出 ${format}`) }
</script>

<template>
  <section class="resource-page"><div class="resource-inner"><header class="resource-header"><div><span class="eyebrow">把知识整理成适合你的材料</span><h1>资源工坊</h1><p>对话中生成的学习资料，都在这里汇集</p></div><button class="create-resource" @click="router.push('/question-nav-chat')"><Sparkles :size="16" />去对话生成</button></header><div class="search-wrap"><Search :size="18" :stroke-width="1.4" /><input v-model="search" placeholder="搜索资源名称或描述..." /></div><div class="filter-tabs"><button v-for="item in filters" :key="item" :class="{active:type===item}" @click="type=item">{{ item }}</button></div><div v-if="filtered.length" class="resource-grid"><article v-for="item in filtered" :key="item.id" class="resource-card"><div class="resource-icon"><component :is="item.icon" :size="22" :stroke-width="1.35" /></div><div class="resource-type">{{ item.type }}</div><h2>{{ item.title }}</h2><p>{{ item.desc }}</p><small>{{ item.meta }}</small><div class="card-actions"><button @click="preview=item"><BookOpen :size="15" />查看</button><div class="export-wrap"><button @click="exportOpen=exportOpen===item.id?null:item.id"><ArrowDownToLine :size="15" />导出</button><div v-if="exportOpen===item.id" class="export-menu"><button @click="exportResource('PPT')">PPT (.pptx)</button><button @click="exportResource('PDF')">PDF (.pdf)</button><button @click="exportResource('Markdown')">Markdown (.md)</button></div></div><button class="delete-action" @click="deleteTarget=item"><Trash2 :size="15" /></button></div></article><button class="create-card" @click="router.push('/question-nav-chat')"><MessagePlaceholder /><strong>去对话页生成</strong><small>在对话中生成新的学习资料</small></button></div><div v-else class="empty-state"><FolderOpen :size="32" :stroke-width="1.25" /><h2>资源工坊是空的</h2><p>去对话辅导页聊一聊 AI 知识，生成的学习资料会自动汇集到这里。</p><button class="create-resource" @click="router.push('/question-nav-chat')">去对话页生成</button></div></div><div v-if="preview" class="modal-backdrop" @click.self="preview=null"><article class="resource-modal"><header><div><span class="eyebrow">{{ preview.type }}</span><h2>{{ preview.title }}</h2><small>生成于 {{ preview.meta }}</small></div><button @click="preview=null"><X :size="19" /></button></header><div class="modal-content"><p>{{ preview.desc }}。这是一份围绕当前学习路径整理的静态演示资料。</p><div class="fake-content"><h3>本资源包含</h3><p>核心概念梳理 · 关键示例 · 自测问题 · 下一步学习建议</p><div v-if="preview.type === '闪卡'" class="flashcard"><span>第 3 / 12 张</span><strong>卷积核（Kernel）是什么？</strong><button>点击翻转</button></div><div v-if="preview.type === '项目'" class="project-steps"><span>✓ 1. 环境搭建</span><span>✓ 2. 数据准备</span><span>› 3. 模型构建</span><span>○ 4. 训练调参</span></div></div></div><footer><div class="modal-exports"><button @click="exportResource('PPT')">导出 PPT</button><button @click="exportResource('PDF')">导出 PDF</button><button @click="exportResource('Markdown')">导出 Markdown</button></div><button class="create-resource" @click="preview=null">关闭</button></footer></article></div><div v-if="deleteTarget" class="modal-backdrop" @click.self="deleteTarget=null"><section class="confirm-modal"><button class="close-confirm" @click="deleteTarget=null"><X :size="18" /></button><h2>确定删除「{{ deleteTarget.title }}」吗？</h2><p>删除后无法恢复。</p><footer><button class="outline-action" @click="deleteTarget=null">取消</button><button class="danger-button" @click="remove">确认删除</button></footer></section></div></section>
</template>

<script lang="ts">import { defineComponent, h } from 'vue'; import { MessageCircle } from '@lucide/vue'; const MessagePlaceholder = defineComponent({ render: () => h(MessageCircle, { size: 32, strokeWidth: 1.2 }) })</script>

